export const categories = ['Canned goods', 'Dry goods', 'Produce', 'Toiletries'] as const;

export type Category = (typeof categories)[number];

export type PantryItem = {
  id: string;
  name: string;
  category: Category;
  quantity: number;
  /** The day the item was last restocked, as `YYYY-MM-DD`. */
  restocked: string;
};

/** Below this many on hand, an item reads as low stock. */
export const lowStock = 10;

export const sampleItems: PantryItem[] = [
  { id: 'chickpeas', name: 'Chickpeas', category: 'Canned goods', quantity: 24, restocked: '2026-10-02' },
  { id: 'chopped-tomatoes', name: 'Chopped tomatoes', category: 'Canned goods', quantity: 6, restocked: '2026-09-21' },
  { id: 'brown-rice', name: 'Brown rice, 1 kg', category: 'Dry goods', quantity: 18, restocked: '2026-10-05' },
  { id: 'rolled-oats', name: 'Rolled oats', category: 'Dry goods', quantity: 9, restocked: '2026-09-28' },
  { id: 'apples', name: 'Apples', category: 'Produce', quantity: 40, restocked: '2026-10-08' },
  { id: 'potatoes', name: 'Potatoes', category: 'Produce', quantity: 15, restocked: '2026-10-07' },
  { id: 'toothpaste', name: 'Toothpaste', category: 'Toiletries', quantity: 12, restocked: '2026-09-30' },
  { id: 'bar-soap', name: 'Bar soap', category: 'Toiletries', quantity: 4, restocked: '2026-09-15' },
];

export function today(): string {
  const now = new Date();
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'long' });

export function formatDate(day: string): string {
  const [year, month, date] = day.split('-').map(Number);
  return dateFormat.format(new Date(year!, month! - 1, date!));
}

export function slug(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}
EOF
